#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Padrinho production deploy (PLAN.md §11, phase 8). Run on the Linux server from the cloned
# repo: ./scripts/deploy-wizard.sh   Safe to re-run: values already in .env are kept on Enter.

run_wizard() {

cd "$(dirname "$0")/.."
REPO_DIR=$(pwd)
TOTAL_STAGES=9

banner "Padrinho · deploy no servidor"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
say "Vou conferir se o servidor tem o que o bot precisa."
missing=0
for cmd in docker git curl tailscale; do
  if command -v "$cmd" >/dev/null 2>&1; then
    note "✓ $cmd"
  else
    warn "falta: $cmd"; missing=1
  fi
done
if docker compose version >/dev/null 2>&1; then note "✓ docker compose"; else warn "falta: docker compose (plugin)"; missing=1; fi
if (( missing )); then
  say ""
  say "Instale o que falta e rode o wizard de novo:"
  step "Docker + compose:  curl -fsSL https://get.docker.com | sh"
  step "Tailscale:         curl -fsSL https://tailscale.com/install.sh | sh"
  step "git/curl:          sudo apt install -y git curl   (Debian/Ubuntu)"
  exit 1
fi
if ! docker info >/dev/null 2>&1; then
  warn "seu usuário não consegue falar com o Docker."
  step "Rode: sudo usermod -aG docker \$USER   e entre de novo no SSH."
  exit 1
fi
pause "Tudo certo. Enter para continuar."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Código mais recente"
say "Repositório: $REPO_DIR"
git -C "$REPO_DIR" fetch --quiet origin
say "Commit atual: $(git -C "$REPO_DIR" log -1 --format='%h %s')"
if [[ -n "$(git -C "$REPO_DIR" status --porcelain -- src scripts package.json Dockerfile)" ]]; then
  warn "há mudanças locais no código deste servidor; não vou sobrescrever."
elif confirm "Atualizar para o último commit da master (git pull)?"; then
  git -C "$REPO_DIR" pull --ff-only origin master
fi
say "Agora em: $(git -C "$REPO_DIR" log -1 --format='%h %s')"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Configuração de produção (.env)"
say "Use os mesmos valores do .env do seu PC (pasta do projeto Godfather)."
open_url "https://discord.com/developers/applications"
step "Token: aplicação Padrinho → Bot → Reset Token (ou reaproveite o do PC)."
ask_secret DISCORD_TOKEN "DISCORD_TOKEN (fica oculto):"
step "Application ID: aba General Information."
ask DISCORD_CLIENT_ID "DISCORD_CLIENT_ID:"
step "ID do servidor M4F1A: botão direito no ícone do servidor → Copiar ID."
ask DISCORD_GUILD_ID "DISCORD_GUILD_ID:"
write_env DISCORD_TOKEN "$DISCORD_TOKEN"
write_env DISCORD_CLIENT_ID "$DISCORD_CLIENT_ID"
write_env DISCORD_GUILD_ID "$DISCORD_GUILD_ID"
current_url=$(_existing PUBLIC_BASE_URL || true)
write_env PUBLIC_BASE_URL "${current_url:-https://padrinho.example.ts.net}"   # real URL in stage 7
write_env NODE_ENV production
write_env LOG_LEVEL info
write_env HTTP_PORT 8080
write_env DISCORD_MESSAGE_CONTENT "$(_existing DISCORD_MESSAGE_CONTENT || echo false)"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Parar o bot do PC"
warn "Dois bots com o mesmo token respondem em dobro e duplicam os avisos."
say "No PC, pare o Padrinho que roda em modo dev:"
step "Feche o terminal do 'npm run dev' / 'tsx src/index.ts', ou peça ao Claude para parar o bot."
step "Confira no Discord: o Padrinho deve ficar offline (bolinha cinza) em ~1 minuto."
until confirm "O bot do PC está parado (Padrinho offline no Discord)?"; do
  say "Sem pressa. Pare o bot do PC e responda y."
done

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Trazer o banco atual do PC"
say "O banco guarda os IDs criados pelo /setup, eventos, RSVPs, salas e tokens MCP."
mkdir -p "$REPO_DIR/data"
replace_db=1
if [[ -f "$REPO_DIR/data/padrinho.db" ]]; then
  note "já existe data/padrinho.db aqui."
  confirm "Substituir pelo banco do PC?" || replace_db=0
fi
if (( replace_db )); then
  say "No PC (PowerShell, dentro da pasta do projeto), com o bot parado, rode:"
  step "scp data/padrinho.db $(whoami)@$(hostname):$REPO_DIR/data/"
  note "Se existir data/padrinho.db-wal ao lado, copie-o também."
  until [[ -f "$REPO_DIR/data/padrinho.db" ]] && confirm "Copiou? (data/padrinho.db já está aqui)"; do
    pause "Copie o arquivo e tecle Enter."
  done
fi
say "O container roda como o usuário node (uid 1000); ajustando o dono da pasta data:"
sudo chown -R 1000:1000 "$REPO_DIR/data"
note "✓ data/ pertence ao uid 1000"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Subir o container"
say "Construindo a imagem e subindo (pode levar alguns minutos na primeira vez)…"
docker compose up -d --build
say "Esperando o /healthz…"
healthy=0
for _ in $(seq 1 60); do
  if curl -fsS http://127.0.0.1:8080/healthz >/dev/null 2>&1; then healthy=1; break; fi
  sleep 2
done
if (( healthy )); then
  note "✓ $(curl -fsS http://127.0.0.1:8080/healthz)"
else
  warn "o bot não ficou saudável em 2 minutos. Últimos logs:"
  docker compose logs --tail 40 padrinho
  exit 1
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "URL pública (Tailscale Funnel)"
say "O Funnel publica a porta 8080 com HTTPS para o Claude Code/Codex/OpenCode alcançarem o MCP."
if ! tailscale status >/dev/null 2>&1; then
  step "Conecte este servidor à sua tailnet (vai mostrar um link de login):"
  sudo tailscale up
fi
note "Na primeira vez, o Tailscale mostra um link para ativar HTTPS/Funnel na tailnet: abra e aprove."
sudo tailscale funnel --bg 8080
funnel_url=$(tailscale funnel status 2>/dev/null | grep -oE 'https://[A-Za-z0-9.-]+\.ts\.net' | head -n1 || true)
if [[ -z "$funnel_url" ]]; then
  warn "não consegui ler a URL do Funnel automaticamente."
  ask funnel_url "Cole a URL https://...ts.net mostrada por 'tailscale funnel status':"
fi
write_env PUBLIC_BASE_URL "$funnel_url"
docker compose up -d   # recreate the container with the new PUBLIC_BASE_URL
sleep 5
if curl -fsS "$funnel_url/healthz" >/dev/null 2>&1; then
  note "✓ $funnel_url/healthz responde de fora"
else
  warn "$funnel_url/healthz ainda não responde (o DNS do Funnel pode levar 1-2 min). Teste depois."
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Backup diário"
say "Backup do banco todo dia às 04:15, guardando 14 dias em data/backups."
cron_line="15 4 * * * $REPO_DIR/scripts/backup.sh >> \$HOME/padrinho-backup.log 2>&1"
if crontab -l 2>/dev/null | grep -qF "$REPO_DIR/scripts/backup.sh"; then
  note "✓ já está no crontab"
elif confirm "Adicionar ao seu crontab?"; then
  (crontab -l 2>/dev/null || true; echo "$cron_line") | crontab -
  note "✓ crontab: $cron_line"
else
  SKIPPED+=("backup diário: adicione ao crontab → $cron_line")
fi
say "Rodando um backup agora para testar:"
"$REPO_DIR/scripts/backup.sh"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Conferir e reconectar as IAs"
say "MCP sem token deve responder 401:"
code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$PUBLIC_BASE_URL/mcp" || true)
if [[ "$code" == "401" ]]; then note "✓ $PUBLIC_BASE_URL/mcp → 401"; else warn "$PUBLIC_BASE_URL/mcp → $code"; fi
step "No Discord: o Padrinho deve estar online e /event list, /boss list etc. funcionando."
step "No PC, aponte o Claude Code para a nova URL (os tokens do banco continuam valendo):"
note "  claude mcp remove padrinho"
note "  claude mcp add --transport http padrinho $PUBLIC_BASE_URL/mcp --header \"Authorization: Bearer SEU_TOKEN\""
note "Codex / OpenCode: troque a url para $PUBLIC_BASE_URL/mcp (docs/PLAN.md §8.4)."
note "Atualizar no futuro: git pull && docker compose up -d --build   (ou rode este wizard de novo)."
pause "Enter para o resumo."

finish
}

run_wizard "$@"; exit
